// Parse HSBC Taiwan credit card transaction alert email HTML
// Each email contains exactly one transaction
//
// TODO: Implement parsing once a real HSBC email sample is available.
// For now this is a placeholder that extracts no transactions.
// Extraction strategy (try in order):
//   1. HTML table extraction — <table> → <tr> → <td>
//   2. Labeled field extraction — patterns like 交易金額.*?([\d,]+)
//   3. Fallback regex extraction — date, amount, 4-digit card in full body

const items = [];

for (const item of $input.all()) {
  const html = item.json.textHtml || '';
  const emailDate = item.json.date;
  const messageId = item.json.id;

  // Placeholder: push an error item so the filter node drops it
  items.push({
    json: {
      error: 'HSBC parser not yet implemented — awaiting email sample',
      messageId,
      emailDate
    }
  });
