return items;

// Transform parsed HSBC transactions into YNAB API format
// YNAB uses milliunits: 1 TWD = 1000 milliunits
// Spending is negative (outflow)

// Configuration - UPDATE THESE VALUES
const YNAB_ACCOUNT_ID = '{{ $env.YNAB_ACCOUNT_ID || "CONFIGURE_ME" }}';

const transactions = [];

for (const item of $input.all()) {
  const tx = item.json;

  // Parse and normalize the date to ISO 8601 (YYYY-MM-DD)
  let isoDate;
  const dateStr = tx.transactionDate || '';

  if (/\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2}/.test(dateStr)) {
    // YYYY/MM/DD or YYYY-MM-DD
    const parts = dateStr.split(/[\/\-]/);
    isoDate = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
  } else if (/\d{1,2}[\/\-]\d{1,2}[\/\-]\d{4}/.test(dateStr)) {
    // MM/DD/YYYY
    const parts = dateStr.split(/[\/\-]/);
    isoDate = `${parts[2]}-${parts[0].padStart(2, '0')}-${parts[1].padStart(2, '0')}`;
  } else {
    // Fallback to email date
    const d = new Date(tx.emailDate);
    isoDate = d.toISOString().split('T')[0];
  }

  // Convert amount to milliunits (negative for outflows/spending)
  const milliunits = Math.round(tx.amount * -1000);

  // Build memo from card info
  const memo = tx.cardLast4 ? `Card: ****${tx.cardLast4}` : '';

  // Generate import_id for deduplication
  // Format: YNAB:milliunit_amount:iso_date:occurrence
  const baseImportId = `YNAB:${milliunits}:${isoDate}`;
  const occurrence = transactions.filter(t =>
    t.import_id && t.import_id.startsWith(baseImportId)
  ).length + 1;

  transactions.push({
    account_id: YNAB_ACCOUNT_ID,
    date: isoDate,
    amount: milliunits,
    payee_name: tx.merchant,
    memo: memo,
    cleared: 'cleared',
    import_id: `${baseImportId}:${occurrence}`
  });
}

return [{
  json: {
    transactions: transactions
  }
}];
